```xUnit Test Cases

namespace VirtualClinicTests
{
    [TestFixture]
    public class SymptomDeletionTests
    {
        [Test]
        public void SymptomCodeCannotBeDeletedIfUsedInConsultationRequests()
        {
            // Arrange
            var consultationRequests = new List<ConsultationRequest>
            {
                new ConsultationRequest { SymptomCode = "S123" }
            };

            var symptomCodeManager = new SymptomCodeManager();

            // Act
            var result = symptomCodeManager.DeleteSymptomCode("S123");

            // Assert
            Assert.Throws<Exception>(() => result, "Symptom Code used, cannot be deleted");
        }

        [Test]
        public void SymptomCodeCanBeDeletedIfNotUsedInConsultationRequests()
        {
            // Arrange
            var symptomCodeManager = new SymptomCodeManager();
            symptomCodeManager.DeleteSymptomCode("S123");

            // Act & Assert
            Assert.DoesNotThrow(() => symptomCodeManager.DeleteSymptomCode("S123"));
        }

        [Test]
        public void SymptomCodeDeletionOnHerokuPlatform()
        {
            // Arrange
            var symptomCodeManager = new SymptomCodeManager();
            // Act
            var result = symptomCodeManager.DeleteSymptomCode("S123");

            // Assert
            Assert.DoesNotThrow(() => result);
        }

        [Test]
        public void SymptomCodeDeletionWithSufficientHardDriveSpace()
        {
            // Arrange
            var symptomCodeManager = new SymptomCodeManager();
            // Act
            var result = symptomCodeManager.DeleteSymptomCode("S123");

            // Assert
            Assert.DoesNotThrow(() => result);
        }

        [Test]
        public void SymptomCodeDeletionWithSufficientRAM()
        {
            // Arrange
            var symptomCodeManager = new SymptomCodeManager();
            // Act
            var result = symptomCodeManager.DeleteSymptomCode("S123");

            // Assert
            Assert.DoesNotThrow(() => result);
        }

        [Test]
        public void SymptomCodeDeletionWithSufficientDatabaseSpace()
        {
            // Arrange
            var symptomCodeManager = new SymptomCodeManager();
            // Act
            var result = symptomCodeManager.DeleteSymptomCode("S123");

            // Assert
            Assert.DoesNotThrow(() => result);
        }
    }
}
